def verify_m_equals_2():
    S = list(range(1, 51))
    T = []
    # Construction: A Hamiltonian cycle on 50 vertices
    for i in range(50):
        a = i + 1
        b = (i + 2) % 50 + 1
        T.append({a, b})

    print(f"T has {len(T)} elements.")
    assert len(T) == 50

    # Check condition (a): |A_i| = m = 2
    for A in T:
        assert len(A) == 2
    print("Condition (a) verified.")

    # Check condition (b): Pairwise intersection <= 1
    for i in range(len(T)):
        for j in range(i + 1, len(T)):
            intersection = len(T[i].intersection(T[j]))
            assert intersection <= 1
    print("Condition (b) verified.")

    # Check condition (c): Each element is contained in exactly two elements of T.
    counts = {x: 0 for x in S}
    for A in T:
        for x in A:
            counts[x] += 1

    for x, count in counts.items():
        assert count == 2
    print("Condition (c) verified.")

    print("Verification successful for m=2.")

verify_m_equals_2()
